window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b6bd732870a53017"]={"versions": [{"id": "FIG-b6bd732870a53017", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm / Zeitablaufdiagramm zur Veranschaulichung des Kanalzustands- und Sendeablaufs im LIN Interface (<code>LinIf</code>) der AUTOSAR Classic Platform. Dargestellt ist das Zusammenspiel zwischen periodischen Hauptfunktionsaufrufen (<code>LinIf_MainFunction</code>), Treiber-Aufrufen (<code>Lin</code>), Busaktivität und asynchronen Ereignissen (Wake-up Request durch einen Slave) während des Übergangs in den Schlafmodus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Komponenten</strong>:\n<ul class=\"fig-list\"><li><code>LinIf</code>: LIN Interface mit Zustandslogik (<code>CHANNEL_OPERATITONAL</code>)\n</li><li>LIN Driver (<code>Lin</code>): Treiber zur Ansteuerung des LIN-Busses\n</li><li>LIN Bus: Kommunikationsmedium mit Busaktivität (<code>Bus activity</code>)\n</li><li>LIN Slave: Überträgt Wake-up Request auf dem Bus\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionen</strong>:\n<ul class=\"fig-list\"><li><code>LinIf_GotoSleep</code>: API-Aufruf zum Einleiten des Schlafzustands\n</li><li><code>LinIf_MainFunction</code>: Zyklischer Taskaufruf des LIN-Interfaces (dargestellt durch nach oben gerichtete vertikale Pfeile an der Zeitachse)\n</li><li><code>Lin_GoToSleep</code>: Treiber-API zum Senden des Go-to-sleep-Frames\n</li><li>Go-to-sleep command: Auf dem Bus übertragener Master-Request-Frame\n</li><li>LIN-Treiber-Bestätigung (Confirmation): Bestätigung des Sendens an das LIN Interface\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Vor Beginn der Sequenz befindet sich der Kanal im Zustand <code>CHANNEL_OPERATITONAL</code>.\n</li><li>Asynchron oder vor einem Hauptfunktionszyklus wird <code>LinIf_GotoSleep</code> aufgerufen.\n</li><li>Beim nächsten periodischen Aufruf von <code>LinIf_MainFunction</code> wird <code>Lin_GoToSleep</code> am LIN-Treiber aufgerufen und die Aussendung des Frames „Go-to-sleep command“ auf dem Bus gestartet.\n</li><li>Während bzw. kurz nach der Aussendung des Go-to-sleep-Befehls überträgt ein LIN-Slave einen Wake-up Request auf den Bus.\n</li><li>Zu einem späteren Hauptfunktionsaufruf bestätigt der LIN-Treiber die Übertragung des Go-to-sleep-Befehls.\n</li><li>Da der Wake-up Request zeitlich vor dieser Bestätigung eingegangen ist, wechselt das LIN Interface nicht in den Schlafzustand, sondern verbleibt im Zustand <code>CHANNEL_OPERATITONAL</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ relevant für das Verhalten bei Rennbedingungen (Race Conditions) zwischen Schlafmodus-Aufforderung und gleichzeitigem Wake-up durch Busteilnehmer: Ein empfangener Wake-up Request überschreibt den Wechsel in den Schlafzustand, auch wenn die Bestätigung des Go-to-sleep-Befehls erst danach eintrifft.\n</li><li>Der Kanalzustand <code>CHANNEL_OPERATITONAL</code> (im Diagramm mit Tippfehler <code>CHANNEL_OPERATITONAL</code>) bleibt aktiv.\n</li><li>Entwickler müssen sicherstellen, dass <code>LinIf</code> interne Flags für anstehende Wake-up-Ereignisse führt, um bei Eintreffen der Go-to-sleep-Bestätigung den Zustandswechsel in <code>LINIF_CHANNEL_SLEEP</code> zu verhindern.\n</li></ul>"}, {"id": "FIG-1671f7f99931814e", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm / Zeitablaufdiagramm zur Veranschaulichung des Kanalzustands- und Sendeablaufs im LIN Interface (<code>LinIf</code>) der AUTOSAR Classic Platform. Dargestellt ist das Zusammenspiel zwischen periodischen Hauptfunktionsaufrufen (<code>LinIf_MainFunction</code>), Treiber-Aufrufen (<code>Lin</code>), Busaktivität und asynchronen Ereignissen (Wake-up Request durch einen Slave) während des Übergangs in den Schlafmodus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Komponenten</strong>:\n<ul class=\"fig-list\"><li><code>LinIf</code>: LIN Interface mit Zustandslogik (<code>CHANNEL_OPERATITONAL</code>)\n</li><li>LIN Driver (<code>Lin</code>): Treiber zur Ansteuerung des LIN-Busses\n</li><li>LIN Bus: Kommunikationsmedium mit Busaktivität (<code>Bus activity</code>)\n</li><li>LIN Slave: Überträgt Wake-up Request auf dem Bus\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionen</strong>:\n<ul class=\"fig-list\"><li><code>LinIf_GotoSleep</code>: API-Aufruf zum Einleiten des Schlafzustands\n</li><li><code>LinIf_MainFunction</code>: Zyklischer Taskaufruf des LIN-Interfaces (dargestellt durch nach oben gerichtete vertikale Pfeile an der Zeitachse)\n</li><li><code>Lin_GoToSleep</code>: Treiber-API zum Senden des Go-to-sleep-Frames\n</li><li>Go-to-sleep command: Auf dem Bus übertragener Master-Request-Frame\n</li><li>LIN-Treiber-Bestätigung (Confirmation): Bestätigung des Sendens an das LIN Interface\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Vor Beginn der Sequenz befindet sich der Kanal im Zustand <code>CHANNEL_OPERATITONAL</code>.\n</li><li>Asynchron oder vor einem Hauptfunktionszyklus wird <code>LinIf_GotoSleep</code> aufgerufen.\n</li><li>Beim nächsten periodischen Aufruf von <code>LinIf_MainFunction</code> wird <code>Lin_GoToSleep</code> am LIN-Treiber aufgerufen und die Aussendung des Frames „Go-to-sleep command“ auf dem Bus gestartet.\n</li><li>Während bzw. kurz nach der Aussendung des Go-to-sleep-Befehls überträgt ein LIN-Slave einen Wake-up Request auf den Bus.\n</li><li>Zu einem späteren Hauptfunktionsaufruf bestätigt der LIN-Treiber die Übertragung des Go-to-sleep-Befehls.\n</li><li>Da der Wake-up Request zeitlich vor dieser Bestätigung eingegangen ist, wechselt das LIN Interface nicht in den Schlafzustand, sondern verbleibt im Zustand <code>CHANNEL_OPERATITONAL</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ relevant für das Verhalten bei Rennbedingungen (Race Conditions) zwischen Schlafmodus-Aufforderung und gleichzeitigem Wake-up durch Busteilnehmer: Ein empfangener Wake-up Request überschreibt den Wechsel in den Schlafzustand, auch wenn die Bestätigung des Go-to-sleep-Befehls erst danach eintrifft.\n</li><li>Der Kanalzustand <code>CHANNEL_OPERATITONAL</code> (im Diagramm mit Tippfehler <code>CHANNEL_OPERATITONAL</code>) bleibt aktiv.\n</li><li>Entwickler müssen sicherstellen, dass <code>LinIf</code> interne Flags für anstehende Wake-up-Ereignisse führt, um bei Eintreffen der Go-to-sleep-Bestätigung den Zustandswechsel in <code>LINIF_CHANNEL_SLEEP</code> zu verhindern.\n</li></ul>"}, {"id": "FIG-d6af88178a5e463c", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm / Zeitablaufdiagramm zur Veranschaulichung des Kanalzustands- und Sendeablaufs im LIN Interface (<code>LinIf</code>) der AUTOSAR Classic Platform. Dargestellt ist das Zusammenspiel zwischen periodischen Hauptfunktionsaufrufen (<code>LinIf_MainFunction</code>), Treiber-Aufrufen (<code>Lin</code>), Busaktivität und asynchronen Ereignissen (Wake-up Request durch einen Slave) während des Übergangs in den Schlafmodus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Komponenten</strong>:\n<ul class=\"fig-list\"><li><code>LinIf</code>: LIN Interface mit Zustandslogik (<code>CHANNEL_OPERATITONAL</code>)\n</li><li>LIN Driver (<code>Lin</code>): Treiber zur Ansteuerung des LIN-Busses\n</li><li>LIN Bus: Kommunikationsmedium mit Busaktivität (<code>Bus activity</code>)\n</li><li>LIN Slave: Überträgt Wake-up Request auf dem Bus\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Funktionen</strong>:\n<ul class=\"fig-list\"><li><code>LinIf_GotoSleep</code>: API-Aufruf zum Einleiten des Schlafzustands\n</li><li><code>LinIf_MainFunction</code>: Zyklischer Taskaufruf des LIN-Interfaces (dargestellt durch nach oben gerichtete vertikale Pfeile an der Zeitachse)\n</li><li><code>Lin_GoToSleep</code>: Treiber-API zum Senden des Go-to-sleep-Frames\n</li><li>Go-to-sleep-Frame (im Diagramm als „Gon() sleep command“ fehlerhaft gerendert): Auf dem Bus übertragener Master-Request-Frame\n</li><li>LIN-Treiber-Bestätigung (Confirmation): Bestätigung des Sendens an das LIN Interface\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Vor Beginn der Sequenz befindet sich der Kanal im Zustand <code>CHANNEL_OPERATITONAL</code>.\n</li><li>Asynchron oder vor einem Hauptfunktionszyklus wird <code>LinIf_GotoSleep</code> aufgerufen.\n</li><li>Beim nächsten periodischen Aufruf von <code>LinIf_MainFunction</code> wird <code>Lin_GoToSleep</code> am LIN-Treiber aufgerufen und die Aussendung des Go-to-sleep-Frames auf dem Bus gestartet.\n</li><li>Während bzw. kurz nach der Aussendung des Befehls überträgt ein LIN-Slave einen Wake-up Request auf den Bus.\n</li><li>Zu einem späteren Hauptfunktionsaufruf bestätigt der LIN-Treiber die Übertragung des Go-to-sleep-Befehls.\n</li><li>Da der Wake-up Request zeitlich vor dieser Bestätigung eingegangen ist, wechselt das LIN Interface nicht in den Schlafzustand, sondern verbleibt im Zustand <code>CHANNEL_OPERATITONAL</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normativ relevant für das Verhalten bei Rennbedingungen (Race Conditions) zwischen Schlafmodus-Aufforderung und gleichzeitigem Wake-up durch Busteilnehmer: Ein empfangener Wake-up Request überschreibt den Wechsel in den Schlafzustand, auch wenn die Bestätigung des Go-to-sleep-Befehls erst danach eintrifft.\n</li><li>Der Kanalzustand <code>CHANNEL_OPERATITONAL</code> (im Diagramm mit Tippfehler <code>CHANNEL_OPERATITONAL</code>) bleibt aktiv.\n</li><li>Entwickler müssen sicherstellen, dass <code>LinIf</code> interne Flags für anstehende Wake-up-Ereignisse führt, um bei Eintreffen der Go-to-sleep-Bestätigung den Zustandswechsel in <code>LINIF_CHANNEL_SLEEP</code> zu verhindern.\n</li></ul>"}], "trans": [{"from": "FIG-b6bd732870a53017", "to": "FIG-1671f7f99931814e", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1671f7f99931814e", "to": "FIG-d6af88178a5e463c", "fr": "R3.0.7", "tr": "R3.1.5", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung des blauen Rahmens auf der Zeitachse: Durch einen Darstellungs-/Renderingfehler ist der Text „Go-to-sleep command“ zu „Gon() \\n sleep command“ korrumpiert und vertikal verschoben.\n</li></ul>"}]};
